var EXPORTS={quote:quote, BASE:BASE, ADDON:ADDON};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.RateCardForgePure = EXPORTS; }
